import { createElement, useEffect, useLayoutEffect, useRef, useState } from "react";
import Autocomplete from "react-google-autocomplete";
import { Link, useLocation, useNavigate } from "react-router-dom";
import {
  Bell,
  CalendarDays,
  Check,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  ClipboardList,
  CreditCard,
  Home,
  LogOut,
  MapPin,
  MapPinOff,
  ExternalLink,
  LoaderCircle,
  Plus,
  QrCode,
  RefreshCw,
  Search,
  Share2,
  ShieldX,
  Target,
  Trophy,
  X,
  UserRound,
  Users,
} from "lucide-react";
import { useAuth } from "../context/AuthContext";
import { getMyPublicLink } from "../api/publicProfile";
import ShareProfileSheet from "./profileShare/ShareProfileSheet";
import ProfileQrScreen from "./profileShare/ProfileQrScreen";
import usePlayerIdentity from "../hooks/usePlayerIdentity";
import { greetingFor, homeAreaLabel } from "../utils/homeHeader";
import { getStoredAuthToken } from "../services/authToken";
import { usableAvatar } from "../utils/avatar";
import {
  extractNotificationList,
  getNotificationCount,
  unreadNotificationCount,
  getNotifications,
} from "../api/notification";
import {
  DEFAULT_RADIUS_MILES,
  formatLocationPill,
  getStoredLocation,
  getStoredLocationLabel,
  getStoredLocationRadius,
  hasLocationDraftChanged,
  initialLocationState,
  storeLocation,
  storeLocationLabel,
  storeLocationArea,
  getStoredLocationArea,
  locationNameFromReverseGeocode,
  readPlaceArea,
  storeLocationRadius,
  USER_LOCATION_CHANGED_EVENT,
  USER_LOCATION_REQUEST_EVENT,
} from "../utils/userLocation";
import { getAuthNavState } from "../utils/authNavState";
import { isMyWeekEnabled } from "../utils/featureFlags";
import { isTabActive, primaryNavTabs } from "../utils/navTabs";
import { badgeLabel, useMyWeekBadge } from "../features/myWeek/useMyWeek";
import "./AppNav.css";

// The desktop links, from the same list as the mobile tabs (utils/navTabs). Leagues isn't one:
// on desktop it lives in the user menu, and under Play once My Week is on.
const NAV_ICONS = { home: Home, coaches: Users, schedule: CalendarDays, play: Trophy, "my-week": CalendarDays };
const DESKTOP_LABELS = { coaches: "My Coaches" };

const buildNavItems = (myWeek) =>
  primaryNavTabs(myWeek)
    .filter((tab) => tab.to)
    .map((tab) => ({
      key: tab.key,
      label: DESKTOP_LABELS[tab.key] ?? tab.label,
      to: tab.to,
      icon: NAV_ICONS[tab.key],
      match: tab.match,
    }));

const reverseGeocodeDeviceLocation = async ({ latitude, longitude }) => {
  try {
    const query = new URLSearchParams({
      format: "jsonv2",
      lat: latitude.toString(),
      lon: longitude.toString(),
    });
    const response = await fetch(`https://nominatim.openstreetmap.org/reverse?${query}`);
    if (!response.ok) return null;
    return locationNameFromReverseGeocode(await response.json());
  } catch {
    return null;
  }
};

const userMenuItems = [
  { label: "Restring Service", to: "/restring", icon: RefreshCw },
  { label: "Restring orders", to: "/restring?screen=orders", icon: ClipboardList },
  { label: "My Leagues", to: "/leagues", icon: Trophy },
  { label: "Player profile", to: "/settings/profile", icon: UserRound },
  { label: "Player match profile", to: "/settings/match-profile", icon: Target },
  { label: "My groups", to: "/groups", icon: Users },
  { label: "Log result", to: "/log-result", icon: Trophy },
  { label: "Ladder", to: "/ladder", icon: Trophy },
  { label: "Payment methods", to: "/settings/payment-methods", icon: CreditCard },
  { label: "Blocked users", to: "/settings/blocked-users", icon: ShieldX },
];


const AppNav = ({
  onNewMatch,
  hideMobileNewMatch = false,
  hideMobileNotifications = false,
  showBack = false,
  onBack,
  hideLocation = false,
  mobileCenter = null,
  // Home's header (home v2): a greeting in place of the wordmark, and a short area name on
  // the location pill.
  homeHeader = false,
}) => {
  const { isAuthenticated, logout, user } = useAuth();
  const myWeekOn = isMyWeekEnabled();
  const navItems = buildNavItems(myWeekOn);
  // Things only this player can answer, on the My Week link (shared with the mobile tab).
  const waitingCount = useMyWeekBadge(myWeekOn && Boolean(isAuthenticated));
  const identity = usePlayerIdentity();
  const authNavState = getAuthNavState({
    isAuthenticated,
    displayName: identity.displayName,
    initials: identity.initials,
    avatarUrl: identity.avatarUrl,
  });
  const { displayName, initials, avatarUrl: rawAvatarUrl } = authNavState;
  // A bucket-root URL is a non-empty string but not a picture; without this the
  // truthy check below renders a broken image instead of the initials.
  const resolvedAvatarUrl = usableAvatar(rawAvatarUrl);
  // Covers the other half: a well-formed URL whose object is missing or expired.
  // Keyed by URL so a later, working one still gets a chance.
  const [failedAvatarUrl, setFailedAvatarUrl] = useState(null);
  const avatarUrl = resolvedAvatarUrl && resolvedAvatarUrl !== failedAvatarUrl ? resolvedAvatarUrl : null;
  const location = useLocation();
  const navigate = useNavigate();
  const [isUserMenuOpen, setUserMenuOpen] = useState(false);
  const [isNotificationsOpen, setNotificationsOpen] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isNotificationsLoading, setNotificationsLoading] = useState(false);
  const [isLocationOpen, setLocationOpen] = useState(false);
  const [locationLabel, setLocationLabel] = useState(getStoredLocationLabel() || "Set location");
  const [locationArea, setLocationArea] = useState(getStoredLocationArea());
  const [locationSearchTerm, setLocationSearchTerm] = useState("");
  const [locationError, setLocationError] = useState("");
  const [locationState, setLocationState] = useState("prompt");
  const [draftLocation, setDraftLocation] = useState(getStoredLocation());
  const [draftLabel, setDraftLabel] = useState(getStoredLocationLabel() || "");
  const [draftArea, setDraftArea] = useState(getStoredLocationArea());
  const [searchRadius, setSearchRadius] = useState(getStoredLocationRadius() ?? DEFAULT_RADIUS_MILES);
  const [committedRadius, setCommittedRadius] = useState(getStoredLocationRadius() ?? DEFAULT_RADIUS_MILES);
  // { slug, enabled } once loaded; false if it couldn't be. Share options show only
  // for an enabled link ("Allow public profile link" in settings).
  const [publicLink, setPublicLink] = useState(null);
  const [shareView, setShareView] = useState(null);
  const userMenuRef = useRef(null);
  const notificationRef = useRef(null);
  const locationSelectionVersionRef = useRef(0);
  const locationRequestVersionRef = useRef(0);
  const openLocationPickerRef = useRef(null);
  const firstName = displayName?.split(" ")?.[0] || "Player";

  // Home's pill shows the short area only when it fits untruncated; otherwise the pin alone.
  // Re-measured when the name or the window changes.
  const homeArea = homeHeader
    ? homeAreaLabel({ area: locationArea, label: locationLabel === "Set location" ? null : locationLabel })
    : null;
  const homeAreaRef = useRef(null);
  const [homeAreaFits, setHomeAreaFits] = useState(true);
  useLayoutEffect(() => {
    if (!homeHeader) return undefined;
    const measure = () => {
      setHomeAreaFits(true);
      requestAnimationFrame(() => {
        const node = homeAreaRef.current;
        setHomeAreaFits(!node || node.scrollWidth <= node.clientWidth);
      });
    };
    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, [homeHeader, homeArea]);
  const ownUserId = user?.user_id ?? user?.id ?? null;
  const canShareProfile = Boolean(publicLink && publicLink.enabled && publicLink.slug);
  // The platform's computed NTRP first. calculated_ntrp is derived per request
  // from current_rating + rating_gender (ttp-api rating_equivalents.js) and ships
  // on the login profile, but this chain used to skip it entirely and settle on
  // usta_rating — the player's own self-declared USTA number — under an "NTRP"
  // label. A player on TPR 7.0 with a computed NTRP of 4.5 was shown 3.5.
  //
  // `??` rather than `||` for the computed value so a legitimate 0 is not treated
  // as absent. The self-declared values below remain as a fallback because
  // calculated_ntrp is null whenever rating_gender is unset, which is the normal
  // state for a self-rating player until an admin fills it in.
  //
  // Ends in null, not a number: there is no default rating. The chain used to end
  // in a hardcoded "4.5", so a player with no rating at all was shown a specific,
  // plausible, entirely invented one.
  const skillLevel =
    user?.calculated_ntrp ??
    user?.profile?.calculated_ntrp ??
    (user?.skillLevel ||
      user?.skill_level ||
      user?.usta_rating ||
      user?.profile?.skillLevel ||
      user?.profile?.skill_level ||
      user?.profile?.usta_rating ||
      null);

  useEffect(() => {
    if (!isUserMenuOpen || !authNavState.isAuthenticated) return undefined;
    let cancelled = false;
    getMyPublicLink()
      .then((link) => {
        if (!cancelled) setPublicLink(link);
      })
      .catch(() => {
        if (!cancelled) setPublicLink((previous) => previous || false);
      });
    return () => {
      cancelled = true;
    };
  }, [isUserMenuOpen, authNavState.isAuthenticated]);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (userMenuRef.current && !userMenuRef.current.contains(event.target)) {
        setUserMenuOpen(false);
      }
      if (notificationRef.current && !notificationRef.current.contains(event.target)) {
        setNotificationsOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Esc closes the profile menu (keyboard support for the folded-in nav links).
  useEffect(() => {
    if (!isUserMenuOpen) return undefined;
    const handleEscape = (event) => {
      if (event.key === "Escape") setUserMenuOpen(false);
    };
    document.addEventListener("keydown", handleEscape);
    return () => document.removeEventListener("keydown", handleEscape);
  }, [isUserMenuOpen]);

  useEffect(() => {
    const token = getStoredAuthToken({ preferScheme: "token" });
    if (!token) return;

    const controller = new AbortController();

    getNotificationCount({ token, signal: controller.signal })
      .then((response) => setUnreadCount(unreadNotificationCount(response)))
      .catch(() => setUnreadCount(0));

    return () => controller.abort();
  }, []);

  useEffect(() => {
    const syncLocationState = () => {
      setLocationLabel(getStoredLocationLabel() || "Set location");
      setLocationArea(getStoredLocationArea());
      const storedRadius = getStoredLocationRadius() ?? DEFAULT_RADIUS_MILES;
      setCommittedRadius(storedRadius);
      setSearchRadius(storedRadius);
    };

    syncLocationState();

    // Another surface asking for the picker — the feed's prompt when no
    // location has been set.
    const openOnRequest = () => openLocationPickerRef.current?.();

    window.addEventListener("storage", syncLocationState);
    window.addEventListener(USER_LOCATION_CHANGED_EVENT, syncLocationState);
    window.addEventListener(USER_LOCATION_REQUEST_EVENT, openOnRequest);

    return () => {
      window.removeEventListener("storage", syncLocationState);
      window.removeEventListener(USER_LOCATION_CHANGED_EVENT, syncLocationState);
      window.removeEventListener(USER_LOCATION_REQUEST_EVENT, openOnRequest);
    };
  }, []);

  const loadNotifications = async () => {
    const token = getStoredAuthToken({ preferScheme: "token" });
    if (!token) return;

    setNotificationsLoading(true);
    try {
      const response = await getNotifications({ token, perPage: 10, page: 1 });
      setNotifications(extractNotificationList(response));
    } catch {
      setNotifications([]);
    } finally {
      setNotificationsLoading(false);
    }
  };

  const handleNewMatch = () => {
    if (typeof onNewMatch === "function") {
      onNewMatch();
      return;
    }
    navigate("/create");
  };

  const commitLocationSelection = ({ label, latitude, longitude, area = null }) => {
    locationSelectionVersionRef.current += 1;
    locationRequestVersionRef.current += 1;
    storeLocation({ latitude, longitude });
    storeLocationLabel(label);
    // The header shows the neighbourhood, not the full address. Geolocation
    // gives us no place components, so "Current location" clears it and the
    // header falls back to the short label.
    storeLocationArea(area);
    setLocationArea(area);
    setLocationLabel(label);
    setLocationError("");
    setLocationOpen(false);
  };

  const setDraftLocationSelection = ({ label, latitude, longitude, area = null }) => {
    setDraftLocation({ latitude, longitude });
    setDraftLabel(label);
    setDraftArea(area);
    setLocationSearchTerm(label);
    setLocationError("");
  };

  const handleUseCurrentLocation = () => {
    if (!navigator.geolocation || locationState === "locating") {
      if (!navigator.geolocation) setLocationState("unavailable");
      setLocationError("Geolocation is unavailable in this browser.");
      return;
    }

    const requestVersion = locationRequestVersionRef.current + 1;
    locationRequestVersionRef.current = requestVersion;
    setLocationState("locating");
    setLocationError("");

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const coords = {
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
        };
        if (locationRequestVersionRef.current !== requestVersion) return;
        setDraftLocationSelection({
          ...coords,
          label: "Current location",
          area: null,
        });
        setLocationState("granted");

        const locationName = await reverseGeocodeDeviceLocation(coords);
        if (!locationName || locationRequestVersionRef.current !== requestVersion) return;
        setDraftLocationSelection({ ...coords, ...locationName });
      },
      (error) => {
        if (locationRequestVersionRef.current !== requestVersion) return;
        const blocked = error?.code === error?.PERMISSION_DENIED || error?.code === 1;
        setLocationState(blocked ? "denied" : "unavailable");
        setLocationError(blocked ? "Location permission is blocked." : "We couldn't access your current location.");
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 300000 },
    );
  };

  const handlePlaceSelected = (place) => {
    if (!place) {
      setLocationError("Please choose a location from the suggestions.");
      return;
    }

    const latitude = place.geometry?.location?.lat?.();
    const longitude = place.geometry?.location?.lng?.();
    const label = place.formatted_address || place.name || locationSearchTerm;

    if (
      !label ||
      typeof latitude !== "number" ||
      Number.isNaN(latitude) ||
      typeof longitude !== "number" ||
      Number.isNaN(longitude)
    ) {
      setLocationError("We couldn't read that location. Try another search result.");
      return;
    }

    locationRequestVersionRef.current += 1;
    setDraftLocationSelection({ label, latitude, longitude, area: readPlaceArea(place) });
  };

  const closeLocationPicker = () => {
    locationRequestVersionRef.current += 1;
    setLocationOpen(false);
  };

  const openLocationPicker = async () => {
    const storedLocation = getStoredLocation();
    const storedLabel = getStoredLocationLabel() || "";
    const storedArea = getStoredLocationArea();
    setDraftLocation(storedLocation);
    setDraftLabel(storedLabel);
    setDraftArea(storedArea);
    setLocationSearchTerm("");
    setLocationError("");
    setSearchRadius(getStoredLocationRadius() ?? DEFAULT_RADIUS_MILES);
    setLocationOpen(true);

    let permission = null;
    try {
      if (navigator.permissions?.query) {
        ({ state: permission } = await navigator.permissions.query({ name: "geolocation" }));
      }
    } catch {
      permission = null;
    }

    const nextState = initialLocationState({
      geolocationAvailable: Boolean(navigator.geolocation),
      permission,
    });
    setLocationState(nextState);
    if (nextState === "granted") handleUseCurrentLocation();
  };
  openLocationPickerRef.current = openLocationPicker;

  const isFirstRun = !getStoredLocation();
  const committedLocation = getStoredLocation();
  const storedCommittedRadius = getStoredLocationRadius() ?? DEFAULT_RADIUS_MILES;
  const hasDraftChanges = hasLocationDraftChanged({
    committed: { location: committedLocation, radiusMiles: storedCommittedRadius },
    draft: { location: draftLocation, radiusMiles: searchRadius },
  });

  const applyDraft = () => {
    if (!draftLocation) return;
    storeLocationRadius(searchRadius);
    commitLocationSelection({
      latitude: draftLocation.latitude,
      longitude: draftLocation.longitude,
      label: draftLabel || "Selected location",
      area: draftArea,
    });
  };

  const resetDraft = () => {
    locationRequestVersionRef.current += 1;
    setDraftLocation(committedLocation);
    setDraftLabel(getStoredLocationLabel() || "");
    setDraftArea(getStoredLocationArea());
    setLocationSearchTerm("");
    setSearchRadius(storedCommittedRadius);
    setLocationError("");
    setLocationState(committedLocation ? "granted" : "prompt");
  };

  const radiusProgress = ((searchRadius - 1) / 24) * 100;

  return (
    <>
      {shareView === "sheet" && canShareProfile ? (
        <ShareProfileSheet
          slug={publicLink.slug}
          onClose={() => setShareView(null)}
          onShowQr={() => setShareView("qr")}
        />
      ) : null}
      {shareView === "qr" && canShareProfile ? (
        <ProfileQrScreen
          slug={publicLink.slug}
          onClose={() => setShareView(null)}
          onShareLink={() => setShareView("sheet")}
        />
      ) : null}
      <header
        className={`app-nav${homeHeader ? " app-nav--home" : ""}${mobileCenter ? " app-nav--has-mobile-center" : ""}${
          isUserMenuOpen || isNotificationsOpen ? " app-nav--menu-open" : ""
        }`}
      >
        <div className="app-nav__left">
          {showBack ? (
            <button
              type="button"
              className="app-nav__back"
              aria-label="Go back"
              onClick={onBack}
            >
              <ChevronLeft size={22} />
            </button>
          ) : null}
          {homeHeader ? (
            <div className="app-nav__greeting">
              <Link className="app-nav__logo-tile" to="/" aria-label="The Tennis Plan home">
                <span aria-hidden="true">🎾</span>
              </Link>
              <span className="app-nav__greeting-copy">
                <span className="app-nav__greeting-hello">{greetingFor()}</span>
                <strong className="app-nav__greeting-name">{firstName}</strong>
              </span>
            </div>
          ) : (
            <Link className="app-nav__brand" to="/">
              <span className="app-nav__brand-mark">🎾</span>
              <strong>
                The Tennis <em>Plan</em>
              </strong>
            </Link>
          )}

          {mobileCenter ? <div className="app-nav__mobile-center">{mobileCenter}</div> : null}

          <nav className="app-nav__links" aria-label="Primary">
            {navItems.map((item) => (
              <Link
                key={item.label}
                to={item.to}
                className={isTabActive(location.pathname, item.match) ? "active" : ""}
              >
                {createElement(item.icon, { size: 16 })}
                <span>{item.label}</span>
                {item.key === "my-week" && waitingCount > 0 ? (
                  <span className="app-nav__badge" aria-label={`${waitingCount} waiting on you`}>
                    {badgeLabel(waitingCount)}
                  </span>
                ) : null}
              </Link>
            ))}
          </nav>
        </div>

        <div className="app-nav__right">
          <div className={`app-nav__location-wrap${hideLocation ? " app-nav__location-wrap--mobile-hidden" : ""}`}>
            {homeHeader ? (
              <button
                type="button"
                className="app-nav__location app-nav__location--home"
                title={locationLabel}
                aria-label={homeArea ? `Location: ${homeArea}. Change location` : "Set location"}
                onClick={() => openLocationPickerRef.current?.()}
              >
                <MapPin size={16} aria-hidden="true" />
                {homeArea && homeAreaFits ? (
                  <span ref={homeAreaRef} className="app-nav__location-area">
                    {homeArea}
                  </span>
                ) : null}
                <ChevronDown size={14} aria-hidden="true" />
              </button>
            ) : (
              <button
                type="button"
                className="app-nav__location"
                title={locationLabel}
                onClick={() => openLocationPickerRef.current?.()}
              >
                <MapPin size={14} />
                <span>{formatLocationPill({
                  location: getStoredLocation(),
                  label: locationLabel === "Set location" ? null : locationLabel,
                  area: locationArea,
                  radiusMiles: committedRadius,
                })}</span>
                <ChevronDown size={14} />
              </button>
            )}
          </div>

          {authNavState.isAuthenticated ? (
            <button
              className={`app-nav__new-match${hideMobileNewMatch ? " app-nav__new-match--mobile-hidden" : ""}`}
              type="button"
              onClick={handleNewMatch}
            >
              <Plus size={17} />
              <span>New match</span>
            </button>
          ) : null}

          {authNavState.isAuthenticated ? (
            <div
              className={`app-nav__notifications${hideMobileNotifications ? " app-nav__notifications--mobile-hidden" : ""}`}
              ref={notificationRef}
            >
              <button
                type="button"
                className="app-nav__icon-button"
                aria-label="View notifications"
                aria-haspopup="menu"
                aria-expanded={isNotificationsOpen}
                onClick={() => {
                  const nextState = !isNotificationsOpen;
                  setNotificationsOpen(nextState);
                  if (nextState) {
                    loadNotifications();
                  }
                }}
              >
                <Bell size={20} />
                {unreadCount > 0 ? <span className="app-nav__dot" /> : null}
              </button>

              {isNotificationsOpen ? (
                <div className="app-nav__dropdown app-nav__dropdown--notifications" role="menu">
                  <h3>Notifications</h3>
                  {isNotificationsLoading ? (
                    <p>Loading notifications...</p>
                  ) : notifications.length === 0 ? (
                    <p>No notifications yet.</p>
                  ) : (
                    notifications.map((notification, index) => (
                      <Link
                        key={notification.id ?? index}
                        to="/notifications"
                        className="app-nav__notification"
                        onClick={() => setNotificationsOpen(false)}
                      >
                        <strong>{notification.title ?? "Notification"}</strong>
                        <span>{notification.message ?? notification.body ?? "New update available."}</span>
                      </Link>
                    ))
                  )}
                  <Link to="/notifications" onClick={() => setNotificationsOpen(false)}>
                    See all notifications
                  </Link>
                </div>
              ) : null}
            </div>
          ) : null}

          {authNavState.isAuthenticated ? (
            <div className="app-nav__user" ref={userMenuRef}>
              <button
                type="button"
                className="app-nav__user-trigger"
                aria-label="Open profile menu"
                aria-haspopup="menu"
                aria-expanded={isUserMenuOpen}
                onClick={() => setUserMenuOpen((open) => !open)}
              >
                <span className={`app-nav__avatar${avatarUrl ? " has-image" : ""}`}>
                  {avatarUrl ? (
                    <img
                      src={avatarUrl}
                      alt={`${displayName} profile`}
                      onError={() => setFailedAvatarUrl(avatarUrl)}
                    />
                  ) : (
                    initials
                  )}
                </span>
                <span className="app-nav__user-copy">
                  <strong>{firstName}</strong>
                  {/* No rating yet renders nothing at all — a bare "NTRP" label
                      with no number reads as a loading state or a broken value. */}
                  {skillLevel != null ? <small>NTRP {skillLevel}</small> : null}
                </span>
                <ChevronDown size={16} />
              </button>

              {isUserMenuOpen ? (
                <div className="app-nav__dropdown app-nav__dropdown--user" role="menu">
                  <div className="app-nav__menu-who">
                    <strong>{displayName}</strong>
                    {skillLevel != null ? <span>NTRP {skillLevel}</span> : null}
                  </div>
                  {canShareProfile ? (
                    <>
                      <button
                        type="button"
                        role="menuitem"
                        className="app-nav__menu-item app-nav__menu-item--share"
                        onClick={() => {
                          setUserMenuOpen(false);
                          setShareView("sheet");
                        }}
                      >
                        <Share2 size={16} aria-hidden="true" />
                        <span>Share my profile</span>
                      </button>
                      <button
                        type="button"
                        role="menuitem"
                        className="app-nav__menu-item app-nav__menu-item--profile"
                        onClick={() => {
                          setUserMenuOpen(false);
                          setShareView("qr");
                        }}
                      >
                        <QrCode size={16} aria-hidden="true" />
                        <span>Show my QR code</span>
                      </button>
                    </>
                  ) : null}
                  {canShareProfile || ownUserId ? (
                    <Link
                      to={ownUserId ? `/players/${ownUserId}` : `/p/${publicLink.slug}`}
                      role="menuitem"
                      className="app-nav__menu-item app-nav__menu-item--profile"
                      onClick={() => setUserMenuOpen(false)}
                    >
                      <UserRound size={16} aria-hidden="true" />
                      <span>View my profile</span>
                    </Link>
                  ) : null}
                  <div className="app-nav__menu-divider" aria-hidden="true" />
                  {/* Primary nav links have no home on mobile (app-nav__links is
                      hidden with no hamburger), so fold them into this menu —
                      shown only on mobile via app-nav__menu-item--mobile. */}
                  {navItems.map((item) => (
                    <Link
                      key={item.label}
                      to={item.to}
                      role="menuitem"
                      className="app-nav__menu-item app-nav__menu-item--mobile"
                      onClick={() => setUserMenuOpen(false)}
                    >
                      <item.icon size={16} />
                      <span>{item.label}</span>
                    </Link>
                  ))}
                  {userMenuItems.map((item) => (
                    <Link
                      key={item.label}
                      to={item.to}
                      role="menuitem"
                      className="app-nav__menu-item"
                      onClick={() => setUserMenuOpen(false)}
                    >
                      <item.icon size={16} />
                      <span>{item.label}</span>
                    </Link>
                  ))}
                  <button
                    type="button"
                    role="menuitem"
                    className="app-nav__menu-item app-nav__menu-item--danger"
                    onClick={() => {
                      setUserMenuOpen(false);
                      logout();
                    }}
                  >
                    <LogOut size={15} />
                    <span>Log Out</span>
                  </button>
                </div>
              ) : null}
            </div>
          ) : (
            <Link className="app-nav__new-match" to="/login" state={{ from: location }}>
              <span>Sign in</span>
            </Link>
          )}
        </div>
      </header>

      {isLocationOpen ? (
        <div className="app-nav__location-overlay" onClick={closeLocationPicker}>
          <div className="app-nav__location-sheet" onClick={(event) => event.stopPropagation()}>
            <div className="app-nav__location-handle" />
            <div className="app-nav__location-header">
              <div>
                <h3 className="app-nav__location-title">Choose Location</h3>
                {isFirstRun ? (
                  <p className="app-nav__location-explainer">
                    Coaches, lessons, and matches are ranked by distance from here.
                  </p>
                ) : null}
              </div>
              <button
                type="button"
                className="app-nav__location-close"
                aria-label="Close location picker"
                onClick={closeLocationPicker}
              >
                <X size={18} />
              </button>
            </div>

            <button
              type="button"
              className={`app-nav__location-current app-nav__location-current--${locationState}`}
              onClick={handleUseCurrentLocation}
              disabled={locationState === "locating" || locationState === "denied" || locationState === "unavailable"}
            >
              <span className="app-nav__location-current-icon">
                {locationState === "locating" ? <LoaderCircle size={18} /> : null}
                {locationState === "denied" || locationState === "unavailable" ? <MapPinOff size={17} /> : null}
                {locationState === "granted" ? <MapPin size={17} /> : null}
                {locationState === "prompt" ? <MapPin size={17} /> : null}
              </span>
              <span className="app-nav__location-current-copy">
                <strong>
                  {locationState === "prompt" ? "Use my current location" : null}
                  {locationState === "locating" ? "Getting your location…" : null}
                  {locationState === "granted" ? draftLabel || "Current location" : null}
                  {locationState === "denied" ? "Location is blocked" : null}
                  {locationState === "unavailable" ? "Location is unavailable" : null}
                </strong>
                {locationState === "granted" ? <small>Using your current location</small> : null}
                {locationState === "denied" ? <small>Enable it in your browser settings</small> : null}
                {locationState === "unavailable" ? <small>Enter a location below instead</small> : null}
              </span>
              <span className="app-nav__location-trailing" aria-hidden="true">
                {locationState === "prompt" ? <ChevronRight size={18} /> : null}
                {locationState === "granted" ? <Check size={18} /> : null}
                {locationState === "denied" || locationState === "unavailable" ? <ExternalLink size={16} /> : null}
              </span>
            </button>

            <p className="app-nav__location-hint">
              {locationState === "prompt" ? "Tap to continue — your browser will ask first." : null}
              {locationState === "granted" ? "Tap to refresh" : null}
              {locationState === "denied" ? "Enter a location below instead." : null}
              {locationState === "unavailable" ? "Enter a location below instead." : null}
            </p>

            <p className="app-nav__location-field-label">Or enter a location</p>
            <div className={`app-nav__location-search${locationState === "denied" || locationState === "unavailable" ? " app-nav__location-search--focused" : ""}`}>
              <Search size={16} />
              <Autocomplete
                apiKey={import.meta.env.VITE_GOOGLE_API_KEY || undefined}
                placeholder="Enter your location"
                className="app-nav__location-search-input"
                value={locationSearchTerm}
                onChange={(event) => {
                  setLocationSearchTerm(event.target.value);
                  if (locationError) setLocationError("");
                }}
                onPlaceSelected={handlePlaceSelected}
                options={{
                  types: ["geocode", "establishment"],
                  fields: ["formatted_address", "geometry", "name", "address_components"],
                  componentRestrictions: { country: "us" },
                }}
              />
            </div>

            {locationError ? <p className="app-nav__location-error">{locationError}</p> : null}
            {!import.meta.env.VITE_GOOGLE_API_KEY ? (
              <p className="app-nav__location-tip">
                Add `VITE_GOOGLE_API_KEY` to enable Google location suggestions.
              </p>
            ) : null}

            <div className="app-nav__location-radius">
              <div className="app-nav__location-radius-head">
                <span>Search Radius</span>
                <strong>{searchRadius} miles</strong>
              </div>
              <input
                type="range"
                min="1"
                max="25"
                step="1"
                value={searchRadius}
                onChange={(event) => {
                  const nextRadius = Number(event.target.value);
                  setSearchRadius(nextRadius);
                }}
                className="app-nav__location-slider-input"
                aria-label="Search Radius"
                style={{
                  background: `linear-gradient(90deg, var(--color-primary) 0%, var(--color-primary) ${radiusProgress}%, #e2e8f0 ${radiusProgress}%, #e2e8f0 100%)`,
                }}
              />
            </div>

            <div className={`app-nav__location-actions${isFirstRun ? " app-nav__location-actions--first-run" : ""}`}>
              {!isFirstRun && hasDraftChanges ? (
                <button type="button" className="app-nav__location-reset" onClick={resetDraft}>
                  Reset
                </button>
              ) : null}
              <button
                type="button"
                className={`app-nav__location-apply${isFirstRun ? " app-nav__location-apply--primary" : ""}`}
                onClick={applyDraft}
                disabled={isFirstRun ? !draftLocation : !hasDraftChanges}
              >
                {isFirstRun ? (draftLocation ? "Done" : "Choose a location") : "Apply"}
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </>
  );
};

export default AppNav;
