const ScrollToTop = () => {
  const location = useLocation();
  const scrollResetKey = getScrollResetKey(location);
  const previousScrollResetKey = useRef(scrollResetKey);

  useEffect(() => {
    if (previousScrollResetKey.current === scrollResetKey) return;
    previousScrollResetKey.current = scrollResetKey;
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }, [scrollResetKey]);

  return null;
};

const LocationPermissionGate = () => {
  const { isAuthenticated } = useAuth();
  const hasCheckedRef = useRef(false);

  useEffect(() => {
    if (!isAuthenticated) {
      hasCheckedRef.current = false;
      return;
    }
    if (hasCheckedRef.current) return;
    hasCheckedRef.current = true;

    const openLocationPicker = () => {
      window.setTimeout(requestLocationPicker, 0);
    };

    if (!navigator.geolocation || !navigator.permissions?.query) {
      if (shouldPromptForLocationAfterLogin({ hasSavedLocation: hasStoredLocation(), permission: "unavailable" })) {
        openLocationPicker();
      }
      return;
    }

    let active = true;
    navigator.permissions
      .query({ name: "geolocation" })
      .then(({ state }) => {
        if (
          active &&
          shouldPromptForLocationAfterLogin({ hasSavedLocation: hasStoredLocation(), permission: state })
        ) {
          openLocationPicker();
        }
      })
      .catch(() => {
        if (
          active &&
          shouldPromptForLocationAfterLogin({ hasSavedLocation: hasStoredLocation(), permission: "unavailable" })
        ) {
          openLocationPicker();
        }
      });

    return () => {
      active = false;
    };
  }, [isAuthenticated]);

  return null;
};

// The header on those pages links into the hash routes. Once the player
// navigates anywhere (even to "#/" again), hand over to the app's routes and
// drop the direct path from the URL so a refresh stays where they went.
const DirectPageOrRoutes = () => {
  const location = useLocation();
  const [directPage] = useState(() => (typeof window === "undefined" ? null : readDirectPage(window.location)));
  const [initialKey] = useState(location.key);
  const leftDirectPage = Boolean(directPage) && location.key !== initialKey;

  useEffect(() => {
    if (!leftDirectPage || window.location.pathname === "/") return;
    window.history.replaceState(window.history.state, "", `/${window.location.hash}`);
  }, [leftDirectPage, location.key]);

  if (!directPage || leftDirectPage) return <AppRoutes />;
  if (directPage.payToken) return <PayLinkCheckoutPage token={directPage.payToken} />;
  return isVendorPageEnabled()
    ? <VendorPublicPage vendorSlug={directPage.vendorSlug} />
    : <RestringingPlayerFlow vendorSlug={directPage.vendorSlug} />;
};

// Credits whoever's /p/:slug profile link brought a new player here, once they have an
// account. Mounted once for the whole app so it runs wherever they land after signing up.
const ProfileReferralReporter = () => {
  const { isAuthenticated } = useAuth();
  useReportProfileReferral(isAuthenticated);
  return null;
};

function App() {
  return (
    <AuthProvider>
      <HashRouter>
        <ScrollToTop />
        <AuthDrawerProvider>
          <LocationPermissionGate />
          <ProfileReferralReporter />
          <div className="app-shell">
            <DirectPageOrRoutes />
          </div>
        </AuthDrawerProvider>
      </HashRouter>
    </AuthProvider>
  );
}

export default App;
